/* eslint-disable no-restricted-globals */

import type { ProcessExplorerWindowConfiguration } from "../../../platform/process/common/process.js";
import type { IBootstrapWindow } from "../../../platform/window/electron-sandbox/window.js";
import type { IProcessExplorerMain } from "./processExplorerMain.js";

(async () => {
	const bootstrapWindow: IBootstrapWindow = (window as any)
		.MonacoBootstrapWindow; // defined by bootstrap-window.ts

	const { result, configuration } = await bootstrapWindow.load<
		IProcessExplorerMain,
		ProcessExplorerWindowConfiguration
	>("vs/code/electron-sandbox/processExplorer/processExplorerMain", {
		configureDeveloperSettings: () => ({
			forceEnableDeveloperKeybindings: true,
		}),
	});

	result.startup(configuration);
})();
